const removeBookmark = `-- name: RemoveBookmark :execrows
DELETE FROM post_bookmarks WHERE user_id = $1 AND post_id = $2
`

type RemoveBookmarkParams struct {
	UserID pgtype.UUID `json:"user_id"`
	PostID pgtype.UUID `json:"post_id"`
}

func (q *Queries) RemoveBookmark(ctx context.Context, arg RemoveBookmarkParams) (int64, error) {
	result, err := q.db.Exec(ctx, removeBookmark, arg.UserID, arg.PostID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

