const updatePostSearchVector = `-- name: UpdatePostSearchVector :exec
UPDATE posts
SET search_vector = to_tsvector('english', coalesce(caption, '') || ' ' || coalesce($1::text, ''))
WHERE id = $2
`

type UpdatePostSearchVectorParams struct {
	HashtagText string      `json:"hashtag_text"`
	ID          pgtype.UUID `json:"id"`
}

func (q *Queries) UpdatePostSearchVector(ctx context.Context, arg UpdatePostSearchVectorParams) error {
	_, err := q.db.Exec(ctx, updatePostSearchVector, arg.HashtagText, arg.ID)
	return err
}

const upsertCommentReaction = `-- name: UpsertCommentReaction :one
INSERT INTO comment_reactions (comment_id, user_id, reaction)
VALUES ($1, $2, $3)
ON CONFLICT (comment_id, user_id) DO UPDATE SET reaction = EXCLUDED.reaction, created_at = NOW()
RETURNING comment_id, user_id, reaction, created_at
`

type UpsertCommentReactionParams struct {
	CommentID pgtype.UUID `json:"comment_id"`
	UserID    pgtype.UUID `json:"user_id"`
	Reaction  string      `json:"reaction"`
}

func (q *Queries) UpsertCommentReaction(ctx context.Context, arg UpsertCommentReactionParams) (CommentReaction, error) {
	row := q.db.QueryRow(ctx, upsertCommentReaction, arg.CommentID, arg.UserID, arg.Reaction)
	var i CommentReaction
	err := row.Scan(
		&i.CommentID,
		&i.UserID,
		&i.Reaction,
		&i.CreatedAt,
	)
	return i, err
}

const upsertHashtag = `-- name: UpsertHashtag :one
INSERT INTO hashtags (id, tag)
VALUES ($1, $2)
ON CONFLICT (tag) DO UPDATE SET tag = EXCLUDED.tag
RETURNING id, tag, created_at
`

type UpsertHashtagParams struct {
	ID  pgtype.UUID `json:"id"`
	Tag string      `json:"tag"`
}

func (q *Queries) UpsertHashtag(ctx context.Context, arg UpsertHashtagParams) (Hashtag, error) {
	row := q.db.QueryRow(ctx, upsertHashtag, arg.ID, arg.Tag)
	var i Hashtag
	err := row.Scan(&i.ID, &i.Tag, &i.CreatedAt)
	return i, err
}

